BEGIN TRY BEGIN TRANSACTION; CREATE TABLE dbo.ChangeRequests(ChangeRequestId bigint IDENTITY PRIMARY KEY,RequestPublicId uniqueidentifier NOT NULL UNIQUE,OrganizationId int NOT NULL,TeamId int NULL,EntityKind nvarchar(40) NOT NULL,EntityId nvarchar(80) NOT NULL,OperationCode nvarchar(80) NOT NULL,RiskCode nvarchar(20) NOT NULL,Status nvarchar(30) NOT NULL,RequestedByUserId int NOT NULL,ReviewerUserId int NULL,ProposedJson nvarchar(max) NOT NULL,RowVersion rowversion NOT NULL,CONSTRAINT CK_Candidate_RequestJson CHECK(ISJSON(ProposedJson)=1)); CREATE UNIQUE INDEX UX_Candidate_Pending ON dbo.ChangeRequests(OrganizationId,EntityKind,EntityId) WHERE Status=N'Pending'; CREATE TABLE dbo.ChangeRequestEvents(EventId bigint IDENTITY PRIMARY KEY,ChangeRequestId bigint NOT NULL,EventType nvarchar(50) NOT NULL,ActorUserId int NOT NULL,DecisionKey uniqueidentifier NULL,OccurredAt datetime2(3) NOT NULL,CONSTRAINT FK_Candidate_EventRequest FOREIGN KEY(ChangeRequestId) REFERENCES dbo.ChangeRequests(ChangeRequestId)); INSERT dbo.SchemaVersions(VersionNumber,Description,AppliedAt,AppliedBy) VALUES(N'1.8.0-011',N'R3 candidate 1800_011',SYSUTCDATETIME(),N'candidate-rehearsal'); COMMIT; SELECT N'UP_OK' Result,N'1.8.0-011' Marker; END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK; THROW; END CATCH;